// Study settings are documented against the implemented engine, not topology assumptions.
const section=(heading,paragraphs=[],bullets=[])=>({heading,paragraphs,bullets});
const article=(id,title,summary,sections)=>({id,title,summary,tags:'study overview analysis settings '+title,sections});
export function studyTopic(path){
 const fields={'op.mode':'study-mode','op.window':'study-window','op.interpolationMethod':'study-interpolation','op.domainPolicy':'study-domain','op.fftSize':'study-spectrum','op.balancedOutput':'study-balanced-output','op.balancedInput':'study-balanced-input'};
 if(fields[path])return fields[path];
 const pair=/^op\.(inputPairs|outputPairs)\.(\d+)\.(v|i|polarity)$/.exec(path);
 if(!pair)return null;
 return pair[3]==='polarity'?'study-polarity':`study-${pair[1]==='inputPairs'?'input':'output'}-${pair[3]==='v'?'voltage':'current'}`;
}
export const STUDY_ARTICLES=[
 article('study-mode','Conversion mode: what actually changes','Choose how the tool represents input and output voltage in results.',[
  section('The four modes',[],['DC/DC: Vin is the time-average input voltage; Vout is the time-average output voltage.','AC/DC: Vin is RMS; Vout is the time average.','DC/AC: Vin is the time average; Vout is RMS.','AC/AC: both Vin and Vout are RMS.']),
  section('Effect on results',['The engine computes each mapped voltage over the selected analysis window. If several voltage pairs are mapped on one side, their representative voltages are averaged. These Vin/Vout values label operating points and feed voltage filters, curves and efficiency maps. Example: a zero-mean 230 Vrms sine wave is approximately 0 V in DC mode and 230 V in AC mode over full cycles.']),
  section('What you still configure',['All four modes use the same signed instantaneous-power integral and the same component loss models. Changing mode does not generate waveforms, change switching frequency, choose a topology, enable losses, map signals or enable three-phase scaling. Configure those separately. Imported waveforms are the circuit behaviour being analysed.'])]),
 article('study-window','Analysis window [s]','Select the final steady-state duration used for every operating-point file.',[
  section('Which samples are used',['Enter a positive duration in seconds. The tool takes the last requested duration ending at the final time sample. If the file is shorter, the available record is used. A start boundary between samples is linearly interpolated for every signal. Example: a file from 0 to 0.12 s with a 0.02 s window is analysed from 0.10 to 0.12 s.']),
  section('Effect on calculations',['This window sets average power, time-weighted RMS, conduction averages, switching/recovery events per second, spectra and core flux integration. Changing it can change all losses, efficiency, temperatures and reference-curve coverage. It is not a display-only zoom.']),
  section('Choosing a duration',['Use settled data and preferably whole cycles of the slowest relevant periodic behaviour. One 50 Hz cycle is 0.02 s. Include enough switching cycles to represent event rates. A shorter window can miss events; a nonperiodic boundary produces spectral leakage. A longer window containing startup or drift changes the estimated operating point.'])]),
 article('study-interpolation','Interpolation method','Choose how characteristic reference curves are combined at a requested condition.',[
  section('Reference-curve interpolation',['Query each reference curve first, including inversion when required, then interpolate the returned values across dependency conditions such as temperature, gate voltage or gate resistance. Samples within each curve are treated as a piecewise-linear lookup.']),
  section('Forward family first, then invert',['First interpolate the forward characteristic at the requested dependencies, then invert the combined curve when the engine needs the opposite direction. A flat or nonmonotonic combined curve is rejected because there is no unique inverse. For a forward-direction query, the existing forward lookup is used. This is the default for new studies; saved studies retain their selection.']),
  section('Weighted inverse-distance averaging',['Query reference curves and average their results using inverse squared distance in normalised dependency coordinates. An exact reference condition takes precedence. This is a heuristic rather than rectangular linear interpolation.']),
  section('Effect on losses',['The methods can return different device drops, resistances or energies, especially for nonlinear inverse queries. Those values feed losses and thermal iteration, so comparisons and rankings can change. The method does not change imported waveforms. Use Out-of-domain policy to control requests outside data coverage; origin and zero-floor rules are configured on the characteristic itself.'])]),
 article('study-domain','Out-of-domain policy','Control what happens when a characteristic query exceeds its reference coverage.',[
  section('Available policies',[],['Error outside reference range: reject unsupported curve/dependency queries. A required loss that cannot be computed makes the candidate incomplete; it cannot win the comparison.','Clamp to reference range: evaluate at the nearest supported boundary rather than extending the characteristic. This can conceal a real increase in loss, so inspect diagnostics.','Linear extrapolation: extend a boundary segment or supported dependency model beyond the reference range. The result can be physically implausible; inspect raw projections and warnings.','Legacy compatibility: use the original compatibility rules, including linear curve extrapolation, first-point duplicate handling and legacy dependency/inverse rules. This does not establish physical validity.']),
  section('Example',['For a curve containing (10 A, 0.2 V) and (20 A, 0.5 V), a 1 A request is rejected by Error, returns 0.2 V with Clamp, and extrapolates to -0.07 V with Linear extrapolation. The negative drop magnitude needs explicit review under the tool’s physical-output rules; extrapolation does not automatically approve it.']),
  section('What this changes',['This controls characteristic data coverage, not the waveform time interval. A dependency with only one reference condition remains a fixed-reference assumption. The selected interpolation method and sparse-grid support still determine which queries can be evaluated. Diagnostics retain coverage warnings.'])]),
 article('study-spectrum','Spectral samples','Set the uniform FFT grid used for frequency-dependent ESR and winding resistance.',[
  section('Calculation',['The selected waveform window is linearly resampled onto N uniformly spaced points, then transformed by FFT. Available values are 256, 512, 1024, 2048 and 4096. The DC term and harmonic mean-square currents feed the frequency-dependent resistance loss model.']),
  section('Window length and frequency range',['For an actual window duration T, frequency-bin spacing is 1/T and the grid Nyquist frequency is N/(2T). With T = 1 ms and N = 1024, spacing is 1 kHz and the grid extends to 512 kHz. Raising N extends the grid range; a longer window improves bin spacing. Imported sampling still limits trustworthy bandwidth: resampling cannot recover missing high-frequency information.']),
  section('Effect on the tool',['Changing N can change spectral capacitor ESR and inductor winding losses, required reference-frequency coverage and runtime. Constant-resistance losses use time-domain mean-square current. MOSFET event counting and the core model’s separate automatic frequency estimator do not use this setting. Use whole cycles to reduce leakage and check convergence with adequate source sampling.'])]),
 ...['input','output'].map(side=>article(`study-balanced-${side}`,`Balanced three-phase ${side}: one mapped phase × 3`,`Estimate total three-phase ${side} power from one representative phase.`,[
  section('Meaning and formula',[`Balanced means the three phases have equal average real power. Enable this only when one phase represents all three, and map exactly one phase-to-neutral voltage and its matching phase current. P${side==='output'?'out':'in, mapped'} = 3 × average(vphase(t) × iphase(t) × polarity). The tool multiplies the phase’s average power; it does not reconstruct the other instantaneous phase waveforms.`,`Example: a phase averaging 1 kW represents a total of 3 kW. For sinusoidal balanced signals, total real power is 3 × Vphase,rms × Iphase,rms × cos(phi), not automatically 3 × Vrms × Irms when power factor is below one.`]),
  section(`Effect on ${side} results`,[side==='output'?'The multiplier changes delivered output power and therefore efficiency Pout/(Pout + included losses), along with output-power axes and filters. It does not multiply component losses or device counts. Configure every physical bank and its count separately.':'The multiplier changes the mapped waveform input-power check in the selected-point power-flow dashboard and its discrepancy from calculated input. Reported efficiency still uses Pout/(Pout + included losses), rather than mapped input power. It does not multiply Vin, component losses or device counts.']),
  section('When to leave it off',['For DC, single-phase or split-phase studies, leave this off and map the actual required voltage/current pairs. For an unbalanced three-phase system, map all three phase pairs with ×3 off. Never map all three phases and also enable ×3. Use phase-to-neutral voltage; pairing line-to-line voltage with a phase current does not directly give that phase’s real power.'])])),
 ...['input','output'].flatMap(side=>['voltage','current'].map(quantity=>article(`study-${side}-${quantity}`,`${side==='input'?'Input':'Output'} ${quantity} mapping`,`Choose the imported ${quantity} signal for this ${side} power pair.`,[
  section('Which signal to select',[`Select a ${quantity==='voltage'?'voltage in volts':'current in amperes'} from the imported waveform columns. Signal names must be available in every operating-point file. For AC, match phase-to-neutral voltage with the current of that same phase and align their time samples. For DC, use the voltage and current at the intended converter ${side} boundary.`,quantity==='voltage'?'The voltage is also used to derive the side’s representative Vin/Vout: time average for a DC side, RMS for an AC side as selected in Conversion mode.':'The current keeps its imported sign for the power product. A current magnitude or RMS current alone cannot preserve instantaneous real power or power factor.']),
  section('Effect on calculations',[side==='output'?'Output pair powers are summed and used as delivered output power for efficiency and output-power plots. These mappings do not replace individual component current/voltage mappings.':'Input pair powers are summed for the separate waveform input-power balance check. The input voltage also labels operating points. Individual component losses use their own mappings; mapped input power is not used as the denominator of the reported efficiency.']),
  section('Multiple pairs and phase selection',['Use + Phase pair to add another electrical phase or port, and − Last pair to remove the last row. With ×3 off, all complete voltage/current pairs are summed. With balanced ×3 on, use exactly one complete pair. Use Power polarity to align the signed power with the intended flow direction.'])]))),
 article('study-polarity','Power polarity: +1 or −1','Apply a sign to this pair’s instantaneous voltage × current product.',[
  section('Formula and sign',['Pair power = average(voltage(t) × current(t) × polarity). Select +1 when the imported sign convention gives positive power in the intended direction; select −1 to reverse it. This changes only the pair’s power sign, not the stored waveforms or component currents.']),
  section('Output and input use',['Output pairs must sum to positive delivered power for a valid efficiency. For a regeneration study, map the port delivering power as the study output and choose polarity to match that direction. Input polarity changes the separate mapped-input balance check. Check voltage/current orientation before changing a sign; the setting does not automatically swap ports or rewrite device mappings.']),
  section('Example',['A DC pair with 400 V and -10 A gives -4 kW at +1 and +4 kW at −1. For AC, the sign multiplies the average instantaneous real power; it does not remove reactive power or substitute an apparent-power calculation.'])])
];
